using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---------------------------------------------------

var notepad = new Notepad();

[Description("Search the web for a query and return a list of result snippets. Use this to find information about a topic.")]
static async Task<string> SearchWeb(
    [Description("The search query")] string query)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

    // Use DuckDuckGo HTML search (no API key required)
    var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
    var html = await http.GetStringAsync(url);

    // Extract result snippets from the HTML
    var results = new List<string>();
    var snippetTag = "class=\"result__snippet\"";
    var idx = 0;
    while (results.Count < 6 && (idx = html.IndexOf(snippetTag, idx, StringComparison.Ordinal)) >= 0)
    {
        var start = html.IndexOf('>', idx) + 1;
        var end = html.IndexOf('<', start);
        if (start > 0 && end > start)
        {
            var text = WebUtility.HtmlDecode(html[start..end]).Trim();
            if (text.Length > 0)
                results.Add(text);
        }
        idx = end;
    }

    return results.Count > 0
        ? string.Join("\n---\n", results)
        : "No results found. Try a different query.";
}

[Description("Save a research note. Use this to record important findings as you research.")]
string SaveNote(
    [Description("Title or label for the note")] string title,
    [Description("The content of the note")] string content)
{
    notepad.Notes.Add((title, content));
    return $"Note saved: \"{title}\" ({content.Length} chars)";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notepad.Notes.Count == 0)
        return "No notes saved yet.";

    var sb = new StringBuilder();
    for (int i = 0; i < notepad.Notes.Count; i++)
    {
        var (title, content) = notepad.Notes[i];
        sb.AppendLine($"[{i + 1}] {title}");
        sb.AppendLine(content);
        sb.AppendLine();
    }
    return sb.ToString();
}

// --- Agent setup -------------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run the Research Agent.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notepad.Notes.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. When given a topic you must:
            1. Search the web multiple times with varied queries to gather broad information.
            2. Save important findings as notes using the SaveNote tool.
            3. After gathering enough information, retrieve your notes with GetNotes.
            4. Produce a well-structured summary with key facts, organized under headings.
            Be thorough — perform at least 2-3 searches before summarizing.
            """),
        new(ChatRole.User, $"Research this topic and provide a summary: {topic}")
    };

    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    var response = await client.GetResponseAsync(messages, chatOptions);

    Console.WriteLine("── Summary ─────────────────────────────────────");
    Console.WriteLine(response.Text);
    Console.WriteLine("────────────────────────────────────────────────\n");
}

// --- Helper types ------------------------------------------------------------

class Notepad
{
    public List<(string Title, string Content)> Notes { get; } = [];
}

