+
+var tools = new[]
+{
+    AIFunctionFactory.Create(SearchWeb),
+    AIFunctionFactory.Create(SaveNote),
+    AIFunctionFactory.Create(GetNotes),
+};
+
+var chatOptions = new ChatOptions { Tools = [.. tools] };
+
+Console.WriteLine("=== Research Agent ===");
+Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");
+
+while (true)
+{
+    Console.Write("> ");
+    var topic = Console.ReadLine()?.Trim();
+    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
+        break;
+
+    notepad.Notes.Clear();
+
+    var messages = new List<ChatMessage>
+    {
+        new(ChatRole.System, """
+            You are a research agent. When given a topic you must:
+            1. Search the web multiple times with varied queries to gather broad information.
+            2. Save important findings as notes using the SaveNote tool.
+            3. After gathering enough information, retrieve your notes with GetNotes.
+            4. Produce a well-structured summary with key facts, organized under headings.
+            Be thorough — perform at least 2-3 searches before summarizing.
+            """),
+        new(ChatRole.User, $"Research this topic and provide a summary: {topic}")
+    };
+
+    Console.WriteLine($"\nResearching \"{topic}\"...\n");
+
+    var response = await client.GetResponseAsync(messages, chatOptions);
+
+    Console.WriteLine("── Summary ─────────────────────────────────────");
+    Console.WriteLine(response.Text);
+    Console.WriteLine("────────────────────────────────────────────────\n");
+}
+
+// --- Helper types ------------------------------------------------------------
+
+class Notepad
+{
+    public List<(string Title, string Content)> Notes { get; } = [];
+}
